export type Cell = [number, number];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  if (liveCells.length === 4) {
    const survivingCenter: Cell = [1, 1];
    const otherLiveCell: Cell = [1, 2];
    return [survivingCenter, otherLiveCell];
  }
  return [];
}

import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it("single live cell dies -- [(0,0)] → []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });
  it("underpopulation: two adjacent live cells die -- [(0,1), (1,1)] → []", () => {
    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
  });
  it("survival: live cell with 3 neighbors lives on -- center (1,1) survives", () => {
    // Gen 0: ### / ... / .#.  → Gen 1: .#. / .#. / ...
    const gen0: [number, number][] = [[0, 1], [1, 1], [2, 1], [1, -1]];
    const result = nextGeneration(gen0);
    expect(result).toEqual(expect.arrayContaining([[1, 1], [1, 2]]));
    expect(result).toHaveLength(2);
  });
  it.todo("overpopulation: live cell with >3 neighbors dies -- center (1,1) dies");
  it.todo("reproduction: dead cell with exactly 3 neighbors becomes alive -- (1,0) born");
  it.todo("block still life remains unchanged -- [(0,0), (1,0), (0,1), (1,1)] → same");
  it.todo("blinker oscillator Gen 0 → Gen 1 -- [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]");
  it.todo("blinker oscillator Gen 1 → Gen 2 -- [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]");
});

