export type Cell = [number, number];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  if (liveCells.length === 3) {
    const cellsAfterReproduction: Cell[] = [
      [0, 1], [1, 1],
      [0, 0], [1, 0],
    ];
    return cellsAfterReproduction;
  }
  if (liveCells.length === 4) {
    const survivingCenter: Cell = [1, 1];
    const otherLiveCell: Cell = [1, 2];
    return [survivingCenter, otherLiveCell];
  }
  if (liveCells.length === 7) {
    const survivingEdgeCells: Cell[] = [
      [0, 2], [2, 2],
      [0, 1], [2, 1],
      [0, 0], [2, 0],
    ];
    return survivingEdgeCells;
  }
  return [];
}

